"""Extraction: synchronise the store with the translation files generated by Ren'Py."""

from __future__ import annotations

import dataclasses
import hashlib
import re
from collections.abc import Sequence
from dataclasses import dataclass, field
from pathlib import Path

from renslate.core.db import Database, utc_timestamp
from renslate.core.errors import MarkupError, ProjectError
from renslate.core.models import LOCKED_ORIGINS, Origin, Slot, Status, Unit, UnitKind
from renslate.core.project import Project
from renslate.core.textio import read_text_file, write_atomic
from renslate.renpy.literals import parse_python_string, quote_python_text
from renslate.renpy.mask import mask
from renslate.renpy.parser import (
    Issue,
    ParsedUnit,
    Severity,
    TranslationScanner,
    fingerprint,
    parse_say,
    string_uid,
)

FLAG_SOURCE_CHANGED = "source_changed"
FLAG_MARKUP_INVALID = "markup_invalid"
_KEPT_STATUSES = frozenset({Status.REVIEWED, Status.QA_FLAGGED})


@dataclass(slots=True)
class ExtractReport:
    files: int = 0
    units: int = 0
    slots: int = 0
    created: int = 0
    source_changed: int = 0
    imported: int = 0
    restored: int = 0
    obsolete: int = 0
    issues: list[Issue] = field(default_factory=list)

    @property
    def errors(self) -> int:
        return sum(1 for issue in self.issues if issue.severity is Severity.ERROR)

    @property
    def warnings(self) -> int:
        return len(self.issues) - self.errors


_STRING_LITERAL_RE = r'(?:"(?:\\.|[^"\\])*"|\'(?:\\.|[^\'\\])*\')'
_UI_PATTERNS = (
    ("show_text", re.compile(rf"^\s*show\s+text\s+(?P<lit>{_STRING_LITERAL_RE})", re.MULTILINE)),
    ("textbutton", re.compile(rf"textbutton\s+(?P<lit>{_STRING_LITERAL_RE})")),
    ("screen_text", re.compile(rf"^\s*text\s+(?P<lit>{_STRING_LITERAL_RE})", re.MULTILINE)),
    ("tooltip", re.compile(rf"tooltip\s+(?P<lit>{_STRING_LITERAL_RE})")),
    ("confirm", re.compile(rf"Confirm\(\s*(?P<lit>{_STRING_LITERAL_RE})")),
    ("notify", re.compile(rf"(?:renpy\.)?[Nn]otify\(\s*(?P<lit>{_STRING_LITERAL_RE})")),
    ("i18n", re.compile(rf"_\(\s*(?P<lit>{_STRING_LITERAL_RE})\s*\)")),
)
_MEDIA_EXTS = (
    ".png",
    ".jpg",
    ".jpeg",
    ".webp",
    ".ogg",
    ".mp3",
    ".wav",
    ".ttf",
    ".otf",
    ".rpy",
    ".rpym",
)
_ALPHABETIC_RE = re.compile(r"[a-zA-Z\u00C0-\u024F\u1EA0-\u1EF9]")
_TAG_STRIP_RE = re.compile(r"\{[^\}]*\}")
_INTERP_STRIP_RE = re.compile(r"\[[^\]]*\]")
_OUTER_TAGS_PREFIX_RE = re.compile(r"^(?:\{[^\}]*\})+")
_OUTER_TAGS_SUFFIX_RE = re.compile(r"(?:\{[^\}]*\})+$")


def _strip_outer_tags(s: str) -> str:
    cleaned = _OUTER_TAGS_PREFIX_RE.sub("", s)
    cleaned = _OUTER_TAGS_SUFFIX_RE.sub("", cleaned)
    return cleaned.strip()


def _has_human_text(s: str) -> bool:
    if not s or s.lower().endswith(_MEDIA_EXTS):
        return False
    cleaned = _TAG_STRIP_RE.sub("", s)
    cleaned = _INTERP_STRIP_RE.sub("", cleaned)
    return bool(_ALPHABETIC_RE.search(cleaned))


def sync_project_ui_strings(project: Project, scanner: TranslationScanner) -> int:
    """Scan game scripts and screens for UI text missing in translation files, syncing them."""
    game_root = project.root / "game"
    if not game_root.is_dir() or not project.tl_root.is_dir():
        return 0

    known_sources = {u.source for u in scanner.units}
    new_entries: list[tuple[str, str]] = []
    seen_new: set[str] = set()

    game_files = sorted(
        [p for p in game_root.rglob("*.rpy") if "tl" not in p.parts],
        key=lambda path: project.relative(path),
    )

    for path in game_files:
        rel = project.relative(path)
        try:
            text_file = read_text_file(path)
        except (UnicodeDecodeError, OSError):
            continue

        for idx, line in enumerate(text_file.lines, start=1):
            sline = line.strip()
            if not sline or sline.startswith("#"):
                continue

            for _, pat in _UI_PATTERNS:
                for match in pat.finditer(line):
                    lit = match.group("lit")
                    val = parse_python_string(lit)
                    if not val or not _has_human_text(val):
                        continue

                    ref = f"{rel}:{idx}"
                    if val not in known_sources and val not in seen_new:
                        seen_new.add(val)
                        new_entries.append((val, ref))

                    inner = _strip_outer_tags(val)
                    if (
                        inner != val
                        and _has_human_text(inner)
                        and inner not in known_sources
                        and inner not in seen_new
                    ):
                        seen_new.add(inner)
                        new_entries.append((inner, ref))

    if not new_entries:
        return 0

    ui_file_path = project.tl_root / "ui_strings.rpy"
    rel_ui_file = project.relative(ui_file_path)

    existing_lines: list[str] = []
    if ui_file_path.is_file():
        try:
            existing_lines = read_text_file(ui_file_path).lines
        except Exception:
            existing_lines = []

    chunks: list[str] = []
    if not existing_lines:
        chunks.append(f"translate {project.config.target_lang} strings:\n")
    else:
        chunks.append("\n".join(existing_lines).rstrip() + "\n")

    for val, ref in new_entries:
        quoted = quote_python_text(val)
        chunks.append(f'\n    # {ref}\n    old "{quoted}"\n    new "{quoted}"\n')

    write_atomic(ui_file_path, "".join(chunks).encode("utf-8"))

    scanner.units = [u for u in scanner.units if u.file != rel_ui_file]
    updated_file = read_text_file(ui_file_path)
    scanner.scan_file(rel_ui_file, updated_file.lines)

    return len(new_entries)


def _scan_raw_script(
    file: str,
    lines: Sequence[str],
    scanner: TranslationScanner,
    stored_by_ref: dict[str, Unit],
    seen_by_content: dict[tuple[str | None, str], str],
) -> None:
    current_label: str | None = None
    label_pattern = re.compile(r"^\s*label\s+(?P<label>[A-Za-z_]\w*)\s*:")

    for idx, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue

        lbl_match = label_pattern.match(line)
        if lbl_match:
            current_label = lbl_match.group("label")
            continue

        say = parse_say(stripped)
        if say is not None and say.text:
            speaker = say.speaker
            source = say.text
            ref = f"{file}:{idx}"

            # If previous unit existed at this exact ref with different source, inherit UID
            if ref in stored_by_ref and stored_by_ref[ref].source != source:
                uid = stored_by_ref[ref].uid
            else:
                key = (speaker, source)
                if key in seen_by_content:
                    uid = seen_by_content[key]
                else:
                    h = hashlib.sha1(
                        f"{speaker or ''}\0{source}".encode(), usedforsecurity=False
                    ).hexdigest()[:16]
                    uid = f"d:{h}"
                    seen_by_content[key] = uid

            fp = fingerprint(lines[idx - 1], lines[idx - 1])
            scanner.units.append(
                ParsedUnit(
                    uid=uid,
                    kind=UnitKind.DIALOGUE,
                    source=source,
                    existing=None,
                    ref=ref,
                    speaker=speaker,
                    label=current_label,
                    file=file,
                    line=idx,
                    anchor_line=idx,
                    fingerprint=fp,
                )
            )
            continue

        for _, pat in _UI_PATTERNS:
            for match in pat.finditer(line):
                lit = match.group("lit")
                val = parse_python_string(lit)
                if not val or not _has_human_text(val):
                    continue
                ref = f"{file}:{idx}"
                uid = string_uid(val)
                fp = fingerprint(lines[idx - 1], lines[idx - 1])
                scanner.units.append(
                    ParsedUnit(
                        uid=uid,
                        kind=UnitKind.UI,
                        source=val,
                        existing=None,
                        ref=ref,
                        speaker=None,
                        label=current_label,
                        file=file,
                        line=idx,
                        anchor_line=idx,
                        fingerprint=fp,
                    )
                )


def scan_project(
    project: Project, database: Database | None = None
) -> tuple[TranslationScanner, int]:
    """Parse every ``.rpy`` file below the translation directory; return the scanner and count."""
    root = project.tl_root
    game_root = project.root / "game"
    search_dir = game_root if game_root.is_dir() else project.root

    # Check if search_dir contains .rpyc files that do not have matching translation files in root
    rpyc_files = sorted(
        [p for p in search_dir.rglob("*.rpyc") if "tl" not in p.parts],
        key=lambda path: project.relative(path),
    )
    if rpyc_files:
        has_unextracted_rpyc = False
        for rpyc_path in rpyc_files:
            rel = rpyc_path.relative_to(search_dir)
            if rel.parts and rel.parts[0] == "game":
                rel = Path(*rel.parts[1:])
            expected_tl = root / rel.with_suffix(".rpy")
            if not expected_tl.is_file():
                source_rpy = rpyc_path.with_suffix(".rpy")
                if not source_rpy.is_file():
                    has_unextracted_rpyc = True
                    break

        if has_unextracted_rpyc:
            from renslate.renpy.rpyc import synthesize_translation_skeletons

            synthesize_translation_skeletons(search_dir, project.config.target_lang)

    if root.is_dir() and any(root.rglob("*.rpy")):
        scanner = TranslationScanner(project.config.target_lang)
        files = sorted(root.rglob("*.rpy"), key=lambda path: project.relative(path))
        for path in files:
            relative = project.relative(path)
            try:
                text_file = read_text_file(path)
            except UnicodeDecodeError as error:
                message = f"không phải UTF-8 hợp lệ: {error}"
                scanner.issues.append(Issue(Severity.ERROR, "bad_encoding", relative, 0, message))
                continue
            scanner.scan_file(relative, text_file.lines)
        sync_project_ui_strings(project, scanner)
        files = sorted(root.rglob("*.rpy"), key=lambda path: project.relative(path))
        return scanner, len(files)

    # Fallback: scan game/*.rpy scripts directly if tl_root does not exist
    if game_root.is_dir():
        files = sorted(
            [p for p in game_root.rglob("*.rpy") if "tl" not in p.parts],
            key=lambda path: project.relative(path),
        )
        if files:
            stored_by_ref: dict[str, Unit] = {}
            if database is not None:
                stored_by_ref = {u.ref: u for u in database.units().values() if u.ref}
            elif project.db_path.is_file():
                try:
                    with project.open_db() as db:
                        stored_by_ref = {u.ref: u for u in db.units().values() if u.ref}
                except Exception:
                    pass

            scanner = TranslationScanner(project.config.target_lang)
            seen_by_content: dict[tuple[str | None, str], str] = {}
            for path in files:
                relative = project.relative(path)
                try:
                    text_file = read_text_file(path)
                except UnicodeDecodeError as error:
                    message = f"không phải UTF-8 hợp lệ: {error}"
                    scanner.issues.append(
                        Issue(Severity.ERROR, "bad_encoding", relative, 0, message)
                    )
                    continue
                _scan_raw_script(relative, text_file.lines, scanner, stored_by_ref, seen_by_content)
            return scanner, len(files)

    raise ProjectError(f"không tìm thấy thư mục dịch: {root} (hãy chạy 'renslate generate')")


def _build_unit(
    parsed: ParsedUnit, existing: str | None, seq: int, previous: Unit | None, now: str
) -> tuple[Unit, bool, bool]:
    """Merge a parsed unit into its stored state; return it with (source_changed, imported)."""
    try:
        masked_source: str | None = mask(parsed.source).text
    except MarkupError:
        masked_source = None

    flags: set[str] = set()
    target: str | None = None
    origin: Origin | None = None
    source_changed = False
    if previous is not None:
        target, origin = previous.target, previous.origin
        flags = set(previous.qa_flags) - {FLAG_MARKUP_INVALID}
        if previous.source != parsed.source:
            source_changed = True
            if origin in LOCKED_ORIGINS and target is not None:
                flags.add(FLAG_SOURCE_CHANGED)
            else:
                target, origin = None, None
                flags.discard(FLAG_SOURCE_CHANGED)
    if previous is not None and existing == previous.source:
        existing = None
    imported = target is None and existing is not None
    if imported:
        target, origin = existing, Origin.IMPORTED
    if masked_source is None:
        flags.add(FLAG_MARKUP_INVALID)

    if FLAG_MARKUP_INVALID in flags:
        status = Status.FAILED
    elif FLAG_SOURCE_CHANGED in flags:
        status = Status.QA_FLAGGED
    elif target is None:
        status = Status.PENDING
    elif previous is not None and previous.status in _KEPT_STATUSES:
        status = previous.status
    else:
        status = Status.TRANSLATED

    unit = Unit(
        uid=parsed.uid,
        kind=parsed.kind,
        seq=seq,
        source=parsed.source,
        status=status,
        ref=parsed.ref,
        speaker=parsed.speaker,
        label=parsed.label,
        masked_source=masked_source,
        target=target,
        origin=origin,
        qa_flags=tuple(sorted(flags)),
        updated_at=previous.updated_at if previous is not None else now,
    )
    return unit, source_changed, imported


def extract(project: Project, database: Database, *, now: str | None = None) -> ExtractReport:
    """Read the translation files and bring the store up to date, idempotently."""
    now = now or utc_timestamp()
    scanner, file_count = scan_project(project, database)
    report = ExtractReport(files=file_count, issues=list(scanner.issues))

    first: dict[str, ParsedUnit] = {}
    existing: dict[str, str | None] = {}
    slots: list[Slot] = []
    for parsed in scanner.units:
        first.setdefault(parsed.uid, parsed)
        if existing.get(parsed.uid) is None:
            existing[parsed.uid] = parsed.existing
        slots.append(
            Slot(parsed.uid, parsed.file, parsed.line, parsed.anchor_line, parsed.fingerprint)
        )

    with database.transaction():
        stored = database.units()
        units_to_save: list[Unit] = []
        for seq, (uid, parsed) in enumerate(first.items()):
            previous = stored.get(uid)
            unit, source_changed, imported = _build_unit(parsed, existing[uid], seq, previous, now)
            if previous is None:
                report.created += 1
            report.source_changed += source_changed
            report.imported += imported
            if previous is not None and previous.status is Status.OBSOLETE:
                report.restored += 1
            if unit != previous:
                units_to_save.append(dataclasses.replace(unit, updated_at=now))
        if units_to_save:
            database.save_units_bulk(units_to_save)
        database.replace_slots(slots)
        if report.errors == 0:
            report.obsolete = database.mark_orphans_obsolete(now)

    report.units = len(first)
    report.slots = len(slots)
    return report


def extract_project(project: Project, *, now: str | None = None) -> ExtractReport:
    """Read the translation files and bring the store up to date for a project."""
    with project.open_db() as database:
        return extract(project, database, now=now)
